<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$customer=customer_required();$id=max(0,scalar_int($_GET['id']??$_POST['id']??0));$ticket=support_ticket_for_customer($id,(int)$customer['id']);if(!$ticket){http_response_code(404);exit('تیکت پیدا نشد.');}
if(is_post()){try{verify_csrf();$action=scalar_string($_POST['action']??'reply');if($action==='reply')support_ticket_customer_reply($id,(int)$customer['id'],scalar_string($_POST['message']??''));elseif($action==='close')db()->prepare("UPDATE support_tickets SET status='closed' WHERE id=? AND customer_id=?")->execute([$id,$customer['id']]);flash('success','تیکت به‌روزرسانی شد.');}catch(Throwable $e){flash('error',public_exception_message($e,'به‌روزرسانی تیکت انجام نشد. دوباره تلاش کنید.'));}redirect(app_url('ticket.php?id='.$id));}
$messages=support_ticket_messages($id);$pageKey='account';$pageTitle=$ticket['ticket_number'].' | '.setting('store_name');$robots='noindex,nofollow';$headExtra='<link rel="stylesheet" href="'.e(asset('css/account-responsive.css')).'">';require BASE_PATH.'/app/views/header.php';?>
<main class="account-detail-page support-page"><div class="container product-page">
<div class="public-page-title"><div><span class="eyebrow-dark">گفت‌وگو با پشتیبانی</span><h1><?=e($ticket['subject'])?></h1><p class="muted"><?=e($ticket['ticket_number'])?> · <?=e(ticket_status_labels()[$ticket['status']]??$ticket['status'])?></p></div><div class="public-page-actions"><a class="btn btn-secondary" href="<?=e(app_url('tickets.php'))?>">همه تیکت‌ها</a></div></div>
<?php foreach(flashes() as $flash):?><div class="flash <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endforeach?>
<div class="ticket-thread"><?php foreach($messages as $message):?><article class="ticket-message <?=$message['sender_type']==='admin'?'ticket-message--admin':'ticket-message--customer'?>"><header><strong><?=$message['sender_type']==='admin'?'پشتیبانی فروشگاه':'شما'?></strong><small><?=e(jalali_format($message['created_at']))?></small></header><p><?=nl2br(e($message['message']))?></p></article><?php endforeach?></div>
<?php if($ticket['status']!=='closed'):?><form method="post" class="checkout-card ticket-reply-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="reply"><div class="field"><label>پاسخ شما</label><textarea name="message" minlength="2" maxlength="5000" rows="5" required></textarea></div><button class="btn btn-primary">ارسال پاسخ</button></form><form method="post" class="ticket-close-form" data-confirm="این تیکت بسته شود؟"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="close"><button class="btn btn-secondary">بستن تیکت</button></form><?php endif?>
</div></main><?php require BASE_PATH.'/app/views/footer.php';
